esqlQuery.esql:
// Alert when a model's worst p99 end-to-end latency over the last 6 hours is more than twice the
// median p99 latency of the same model over the rest of the rule window (the preceding days).
// Quiet models (fewer than 20 requests in the last 6 hours) are ignored.
// Tuning: 6 hours = recent period, 20 = minimum recent requests, 2 = multiple of the baseline.
FROM metrics-openrouter.performance-*
| WHERE openrouter.performance.p99_latency IS NOT NULL AND openrouter.performance.request_count > 0
| EVAL recent = @timestamp >= NOW() - 6 hours
| STATS recent_p99 = MAX(openrouter.performance.p99_latency) WHERE recent, recent_req = SUM(openrouter.performance.request_count) WHERE recent,
        baseline_p99 = MEDIAN(openrouter.performance.p99_latency) WHERE NOT recent
  BY openrouter.performance.model
| WHERE recent_req >= 20 AND recent_p99 > baseline_p99 * 2
| KEEP openrouter.performance.model, recent_p99, baseline_p99, recent_req
